-- 066: three parks and four coasters from RCDB via Carter's screenshots and
-- pins, 2026-10-18 — the missing stops of two travelling rides.
--   Noble Park Funland (Paducah, KY): Jet Star (1985-86), the Beech Bend Jet
--     Star between Beech Bend and Kentucky Kingdom, so it joins 064's set
--     (home Nightmare at Crack Axle Canyon); and Galaxi (SDC, 1987-88).
--   Fun Way Amusement Park (Saginaw, MI): Serpent (SDC Galaxi, 25 Apr 2009 -
--     2019).
--   Galaxi and both Serpents are one ride: Noble Park -> LeSourdsville Lake
--     (1989-2002) -> Fun Way -> Niagara (065, home). LeSourdsville Lake has
--     no pin yet, so its Serpent joins later.
--   Sluggers & Putters (Canal Fulton, OH): Little Dipper (Allan Herschell,
--     since 28 Jul 2015, built 1956), called Lil Dipper Roller Coaster until
--     about 2021 (alias). It came from LeSourdsville Lake too; that row joins
--     it when the park is added.
-- Every statement is guarded, so a second run is a no-op.

INSERT INTO parks (name, lat, lon, region) SELECT 'Fun Way Amusement Park', 43.482684325081685, -83.98650054517466, 'Michigan, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Fun Way Amusement Park');
INSERT INTO parks (name, lat, lon, region) SELECT 'Sluggers & Putters', 40.88014791882578, -81.56594696061028, 'Ohio, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Sluggers & Putters');
INSERT INTO parks (name, lat, lon, region) SELECT 'Noble Park Funland', 37.086567910512855, -88.63848035525695, 'Kentucky, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Noble Park Funland');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Jet Star', 'Noble Park Funland', 'Steel', 'Schwarzkopf', 'Schwarzkopf Jet Star', 44.3, 31.1, 1765.1, 0, NULL, 1, 1985, '1985', 'year', '1986', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Noble Park Funland') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Jet Star' AND park = 'Noble Park Funland');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Galaxi', 'Noble Park Funland', 'Steel', 'SDC', 'SDC Galaxi', 45, NULL, 1919, 0, 110, 1, 1987, '1987', 'year', '1988', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Noble Park Funland') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Galaxi' AND park = 'Noble Park Funland');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Serpent', 'Fun Way Amusement Park', 'Steel', 'SDC', 'SDC Galaxi', 45, NULL, 1919, 0, 110, 1, 2009, '2009-04-25', 'day', '2019', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Fun Way Amusement Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Serpent' AND park = 'Fun Way Amusement Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Little Dipper', 'Sluggers & Putters', 'Steel', 'Allan Herschell', 'Allan Herschell Little Dipper', NULL, NULL, NULL, 0, NULL, 1, 2015, '2015-07-28', 'day', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Sluggers & Putters') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Little Dipper' AND park = 'Sluggers & Putters');
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Lil Dipper Roller Coaster', 'rcdb', date('now') FROM coasters WHERE name = 'Little Dipper' AND park = 'Sluggers & Putters';
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT x.id, h.id FROM coasters h, coasters x WHERE h.name = 'Nightmare at Crack Axle Canyon' AND h.park = 'Six Flags Great Escape' AND x.name = 'Jet Star' AND x.park = 'Noble Park Funland';
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT x.id, h.id FROM coasters h, coasters x WHERE h.name = 'Serpent' AND h.park = 'Niagara Amusement Park & Splash World' AND (x.id = h.id OR (x.name = 'Galaxi' AND x.park = 'Noble Park Funland') OR (x.name = 'Serpent' AND x.park = 'Fun Way Amusement Park'));
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Jet Star' AND c.park = 'Noble Park Funland' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'Noble Park Funland');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Galaxi' AND c.park = 'Noble Park Funland' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'Noble Park Funland');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Serpent' AND c.park = 'Fun Way Amusement Park' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'Fun Way Amusement Park');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Little Dipper' AND c.park = 'Sluggers & Putters' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'Sluggers & Putters');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '066') FROM coasters h WHERE h.name = 'Nightmare at Crack Axle Canyon' AND h.park = 'Six Flags Great Escape' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND json_extract(a.detail, '$.ride') = h.id AND a.detail LIKE '%"via":"066"%');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '066') FROM coasters h WHERE h.name = 'Serpent' AND h.park = 'Niagara Amusement Park & Splash World' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND json_extract(a.detail, '$.ride') = h.id AND a.detail LIKE '%"via":"066"%');
